  let native=false;
  if('BarcodeDetector' in window){try{const formats=await BarcodeDetector.getSupportedFormats();if(formats.includes('qr_code')){scannerDetector=new BarcodeDetector({formats:['qr_code']});native=true}}catch(e){console.warn('Native QR detection unavailable:',e)}}
