function stopFriendScanner(){if(scannerTimer){clearInterval(scannerTimer);scannerTimer=null}scannerStream?.getTracks().forEach(t=>t.stop());scannerStream=null;scannerDetector=null;scannerCanvas=null;const video=document.getElementById('friend-camera');if(video){video.pause();video.srcObject=null}const box=document.getElementById('scanner-box');if(box)box.hidden=true}
