function pagerView(){const h=pagerHistory(),m=h[pagerIndex];return `<div class="pager-device"><div class="pager-top"><span>PING LAH! SG</span><span>● PAGER / 01</span></div><div class="pager-bezel"><div class="pager-lcd ${m&&pagerBlinkId===m.id&&Date.now()<pagerBlinkUntil?'pager-new-blink':''}"><div class="lcd-meta"><span>▂▄▆ ▣</span><span>PAGE ${h.length?pagerIndex+1:0}/${h.length}</span><span>▰</span></div><div class="lcd-label">${m?'FROM '+esc(senderName(m)):'READY TO PAGE'}</div><div class="lcd-code">${m?'PING!':'HELLO!'}</div><div class="lcd-message">${esc(m?.body||'Received pages will appear here.')}</div><div class="lcd-date">${m?new Date(m.created_at).toLocaleString():'NO RECEIVED PAGE'}</div></div></div><div class="pager-controls"><button aria-label="Older received page" onclick="pagerStep(1)" ${!h.length||pagerIndex>=h.length-1?'disabled':''}>◀</button><div class="pager-lights"><i></i><i></i></div><button aria-label="Newer received page" onclick="pagerStep(-1)" ${!h.length||pagerIndex===0?'disabled':''}>▶</button></div><div class="pager-foot">${h.length?`${pagerIndex+1} of ${h.length} latest received pages`:'No received pages yet · latest 25 shown'}</div></div>`}
