async function enablePush(){try{if(!('serviceWorker' in navigator)||!('PushManager' in window)||!('Notification' in window))throw Error('This browser does not support Web Push. On iPhone, add Ping Lah! to your Home Screen and open it from the icon.');if(Notification.permission==='denied')throw Error('Notifications are blocked. Enable them in your phone settings.');const key=(await api('/push/public-key')).publicKey;if(!key)throw Error('Cloudflare push keys are not configured yet');const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Notification permission was not granted');const reg=await navigator.serviceWorker.ready;let sub=await reg.pushManager.getSubscription();if(!sub){const b64=key.replace(/-/g,'+').replace(/_/g,'/');const raw=atob(b64+'='.repeat((4-b64.length%4)%4));sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:Uint8Array.from(raw,c=>c.charCodeAt(0))})}await api('/push/subscribe','POST',{subscription:sub.toJSON()});toast('Notifications enabled! Send yourself a test ping.');updatePushStatus()}catch(e){toast(e.message)}}
