const statusOptions=[['online','🟢 Online'],['away','🟡 Away'],['busy','🔴 Busy'],['brb','🕒 Be Right Back'],['offline','⚪ Appear Offline']];
let messengerProfiles={},presenceSeen={},presencePrimed=false,typingLast=0,typingUntil=0,chatLastIncoming='',nudgePollBusy=false;
const buddyAvatarNames=["Smiling face", "Happy face", "Cool face", "Party face", "Nerd face", "Heart eyes", "Smiling with hearts", "Sleepy face", "Angel face", "Cowboy face", "Ghost", "Alien", "Robot", "Space invader", "Skull", "Jack-o-lantern", "Cat", "Dog", "Fox", "Bear", "Panda", "Koala", "Tiger", "Lion", "Frog", "Monkey", "Penguin", "Chick", "Unicorn", "Octopus", "Butterfly", "Honeybee", "Turtle", "Dinosaur", "Sunflower", "Rainbow", "Star", "Crescent moon", "Sun", "Fire", "Sparkling heart", "Gemstone", "Headphones", "Game controller", "Cassette tape", "Floppy disk", "Pager", "Radio", "Guitar", "Pizza", "Noodles", "Coffee", "Football", "Rocket"];
const buddyAvatars=['🙂','😀','😎','🥳','🤓','😍','🥰','😴','😇','🤠','👻','👽','🤖','👾','💀','🎃','🐱','🐶','🦊','🐻','🐼','🐨','🐯','🦁','🐸','🐵','🐧','🐥','🦄','🐙','🦋','🐝','🐢','🦖','🌻','🌈','⭐','🌙','☀️','🔥','💖','💎','🎧','🎮','📼','💾','📟','📻','🎸','🍕','🍜','☕','⚽','🚀'];
const buddyAvatar=f=>messengerProfiles[f?.id]?.avatar||f?.avatar||'🙂';
function effectVolume(){const n=Number(get('ping_effect_volume',85));return Number.isFinite(n)?Math.max(0,Math.min(100,n))/100:.85}
function setEffectVolume(value){put('ping_effect_volume',Number(value));const label=document.getElementById('effect-volume-label');if(label)label.textContent=value+'%'}
function retroSound(type){if(!get('ping_retro_sounds',false)||document.visibilityState!=='visible'||effectVolume()===0)return;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const ctx=new C();const notes=type==='nudge'?[540,760,540]:type==='online'?[580,780]:[760,980];notes.forEach((freq,i)=>{const o=ctx.createOscillator(),g=ctx.createGain(),t=ctx.currentTime+i*.105;o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(Math.max(.0001,.24*effectVolume()),t+.012);g.gain.exponentialRampToValueAtTime(.0001,t+.09);o.connect(g).connect(ctx.destination);o.start(t);o.stop(t+.1)});setTimeout(()=>ctx.close().catch(()=>{}),800)}catch(e){console.warn('Sound unavailable',e)}}
function showChatFeedback(message){let e=document.getElementById('chat-feedback');if(!e){const h=document.querySelector('.msn-chat-header');if(!h)return;e=document.createElement('div');e.id='chat-feedback';e.className='msn-chat-feedback';h.after(e)}e.textContent=message;e.hidden=false;clearTimeout(showChatFeedback.timer);showChatFeedback.timer=setTimeout(()=>{e.hidden=true},3500)}
function emojiShortcuts(text){return text.replace(/(^|\s)(:\)|:-\)|:\(|:-\(|;\)|; -\)|:P|:p|<3)(?=\s|$)/g,(m,p,x)=>p+({':)':'😊',':-)':'😊',':(':'😢',':-(':'😢',';)':'😉',':P':'😛',':p':'😛','<3':'❤️'}[x]||x))}
function toggleRetroSounds(on){put('ping_retro_sounds',on);if(on)retroSound('online')}
function onChatTyping(){if(!chatPeer)return;const t=Date.now();if(t-typingLast<1800)return;typingLast=t;api('/messenger/typing/'+encodeURIComponent(chatPeer),'POST').catch(()=>{})}
async function pollChatTyping(){if(!chatPeer||page!=='chat')return;try{const r=await api('/messenger/typing/'+encodeURIComponent(chatPeer));const e=document.getElementById('chat-typing');if(e)e.textContent=r.typing?((notes[chatPeer]?.name||friends.find(f=>f.id===chatPeer)?.name||'Friend')+' is typing…'):''}catch(e){console.warn('Typing status',e)}}
async function pollMessengerExtras(){if(!token||document.visibilityState!=='visible')return;try{const r=await api('/messenger/presence');const current=Object.fromEntries((r.friends||[]).map(f=>[f.id,f]));for(const f of r.friends||[]){const active=f.status!=='offline'&&Number(f.last_seen)>0&&Date.now()-Number(f.last_seen)<120000;if(presencePrimed&&active&&!presenceSeen[f.id]&&get('ping_online_alerts',true)&&f.status==='online'){toast('🟢 '+escText(notes[f.id]?.name||f.name)+' is now online');retroSound('online')}presenceSeen[f.id]=active}presencePrimed=true;messengerProfiles=current;if(r.me)me={...me,...r.me};if(page==='messenger')render();else if(page==='chat'){const f=friends.find(x=>x.id===chatPeer);const label=document.querySelector('.msn-chat-identity small');if(f&&label)label.textContent=statusText(f)}}catch(e){console.warn('Presence',e)}await checkNudges()}
const escText=x=>String(x??'');

