function setMessengerStyle(value){if(!['modern','retro'].includes(value))return;messengerStyle=value;put('ping_messenger_style',value);render();toast(value==='retro'?'Retro Messenger enabled':'Modern Messenger enabled')}
function settingsView(){return `<section class="panel settings-panel"><h1>⚙️ Settings</h1><p class="muted">Your account, your look, your preferences — all in one place.</p><h2>👤 My profile</h2><p class="small muted">Update your name, avatar, Messenger status and personal message.</p>${button('Edit my profile →',"nav('profile')",'btnmint btnwide')}<hr><h2>🎨 Device appearance</h2><p class="small muted">Choose how your pager, walkie-talkie and radio look. This setting is saved on this device.</p><div class="device-style-options"><button type="button" class="style-choice ${deviceStyle==='retro'?'is-active':''}" aria-pressed="${deviceStyle==='retro'}" onclick="setDeviceStyle('retro')"><span class="style-icon">📟</span><strong>Retro hardware</strong><small>Plastic moulding, glossy glass and warm wood</small><span class="style-check">${deviceStyle==='retro'?'✓ Selected':'Choose retro'}</span></button><button type="button" class="style-choice ${deviceStyle==='modern'?'is-active':''}" aria-pressed="${deviceStyle==='modern'}" onclick="setDeviceStyle('modern')"><span class="style-icon">✨</span><strong>Modern classic</strong><small>The original clean Ping Lah! device design</small><span class="style-check">${deviceStyle==='modern'?'✓ Selected':'Choose modern'}</span></button></div><hr><h2>💬 Messenger appearance</h2><p class="small muted">Choose the style of your conversations. This is independent of device appearance and saved on this device.</p><div class="device-style-options"><button type="button" class="style-choice ${messengerStyle==='retro'?'is-active':''}" aria-pressed="${messengerStyle==='retro'}" onclick="setMessengerStyle('retro')"><span class="style-icon">💬</span><strong>Retro glossy</strong><small>Colourful, dimensional 2000s chat bubbles</small><span class="style-check">${messengerStyle==='retro'?'✓ Selected':'Choose retro'}</span></button><button type="button" class="style-choice ${messengerStyle==='modern'?'is-active':''}" aria-pressed="${messengerStyle==='modern'}" onclick="setMessengerStyle('modern')"><span class="style-icon">🫧</span><strong>Modern simple</strong><small>Clean, subtle chat bubbles</small><span class="style-check">${messengerStyle==='modern'?'✓ Selected':'Choose modern'}</span></button></div><hr><h2>📷 Pocket Cam</h2><p class="small muted">Choose your camera design, colour and layout. Preferences are saved on this device.</p><label>Camera appearance<select onchange="setCamPref('style',this.value)"><option value="classic" ${camPrefs.style==='classic'?'selected':''}>Classic — metallic digicam</option><option value="modern" ${camPrefs.style==='modern'?'selected':''}>Modern — minimal</option></select></label><label>Camera layout<select onchange="setCamPref('layout',this.value)"><option value="landscape" ${camPrefs.layout==='landscape'?'selected':''}>Horizontal</option><option value="portrait" ${camPrefs.layout==='portrait'?'selected':''}>Vertical</option></select></label><label>Metallic case colour<select onchange="setCamPref('color',this.value)">${Object.keys(camColors).map(c=>`<option value="${c}" ${camPrefs.color===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="setting-check"><input type="checkbox" ${camPrefs.stamp?'checked':''} onchange="setCamPref('stamp',this.checked)"> Orange date and time stamp on photos (default on)</label><hr><h2>🔔 Notifications</h2><p class="small muted">Push notifications are still experimental. Your device and browser determine availability.</p></section>${pushSettings()}`}
function profileView(){return `<section class="panel msn-panel"><h1>⚙️ My profile</h1><p class="muted">Your friend code stays the same when you change your name.</p><label>Display name<input id="profile-name" maxlength="60" value="${esc(me.name)}"></label><label>Messenger status<select id="profile-status">${statusOptions.map(([k,v])=>`<option value="${k}" ${me.status===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Retro buddy avatar<select id="profile-avatar">${buddyAvatars.map((a,i)=>`<option value="${a}" ${(me.avatar||'🙂')===a?'selected':''}>${a} ${buddyAvatarNames[i]}</option>`).join('')}</select></label><label class="setting-check"><input type="checkbox" id="retro-sounds" ${get('ping_retro_sounds',false)?'checked':''} onchange="toggleRetroSounds(this.checked)"> Retro Messenger sounds, including send whoosh (while app is open)</label><label class="setting-check"><input type="checkbox" ${get('ping_online_alerts',true)?'checked':''} onchange="put('ping_online_alerts',this.checked)"> Friend online alerts (while app is open)</label><label>Sound effects volume: <strong id="effect-volume-label">${Math.round(effectVolume()*100)}%</strong><input type="range" min="0" max="100" step="5" value="${Math.round(effectVolume()*100)}" oninput="setEffectVolume(this.value)" aria-label="Sound effects volume"></label><p class="small muted">Sound effects play while Ping Lah! is open and sounds are enabled. iPhone Silent Mode and headphone output are controlled by iOS; background push notification sounds are separate.</p><label>Quick personal message<select id="profile-message-preset" onchange="choosePersonalMessage(this.value)"><option value="">✨ Pick a classic MSN-style message…</option>${personalMessagePresets.map(p=>`<option value="${esc(p)}">${esc(p)}</option>`).join('')}</select></label><label>Personal message<input id="profile-message" maxlength="120" placeholder="Or write your own message… 🎵" value="${esc(me.status_message||'')}"></label><p class="small muted">Pick a classic or type your own. Tap Save profile to keep it.</p>${button('Save profile','saveProfile()','btnaccent btnwide')}<p class="small muted">Online and Away reflect recent activity. Appear Offline hides your presence.</p></section>`}
async function saveProfile(){try{const name=$('#profile-name').value.trim(),status=$('#profile-status').value,status_message=$('#profile-message').value.trim(),avatar=$('#profile-avatar').value;if(!name)throw Error('Enter a display name');await api('/me','PATCH',{name,status,status_message,avatar});const confirmed=await api('/me');me=confirmed.me;if(me.avatar!==avatar){throw Error('Avatar was not saved. Please check that the v27 backend is deployed.')}await refresh();toast('Profile saved · '+avatar)}catch(e){toast(e.message)}}
function statusText(f){const x=messengerProfiles[f.id]||f;const st=x.status||'offline';if(st==='offline'||!x.last_seen||Date.now()-Number(x.last_seen)>120000)return '⚪ Offline';return (statusOptions.find(o=>o[0]===st)||statusOptions[4])[1]}
function messengerListView(){const fs=orderedRecipients();return `<section class="panel msn-panel"><div class="msn-title">💬 Ping Lah! Messenger <span>● ● ●</span></div><div class="msn-my-profile"><strong>${esc(me.name)}</strong> <span>${esc(statusText(me))}</span><div class="small muted">${esc(me.status_message||'Set your personal message in My profile')}</div>${button('Edit my name & status',"nav('profile')",'pill')}</div><h2>Friends (${fs.length})</h2>${fs.map(f=>`<button class="msn-friend" onclick="openChat('${f.id}')"><span class="msn-avatar">${esc(buddyAvatar(f))}</span><span><strong>${esc(notes[f.id]?.name||f.name)}</strong><small>${esc(statusText(f))}${messengerProfiles[f.id]?.status_message?' · '+esc(messengerProfiles[f.id].status_message):''}</small></span><span>›</span></button>`).join('')||'<p class="muted">Add a friend to start chatting.</p>'}<p class="small muted">Private one-to-one conversations. Text and emoji only.</p></section>`}
async function loadMessengerFriends(){try{const r=await api('/messenger/presence');messengerProfiles=Object.fromEntries((r.friends||[]).map(x=>[x.id,x]));if(r.me)me={...me,...r.me};if(page==='messenger')render()}catch(e){console.warn('Messenger friends',e)}}
async function sendNudge(){if(!chatPeer)return;const peer=chatPeer;const f=friends.find(x=>x.id===peer);const name=notes[peer]?.name||f?.name||'your friend';try{await api('/messenger/nudge/'+encodeURIComponent(peer),'POST');showChatFeedback('✨ You’ve sent '+name+' a nudge!');const b=document.querySelector('.msn-chat-nudge');if(b){b.classList.remove('nudge-shake');void b.offsetWidth;b.classList.add('nudge-shake')}retroSound('nudge')}catch(e){showChatFeedback('Could not send nudge: '+e.message)}}
async function checkNudges(){if(nudgePollBusy)return;nudgePollBusy=true;try{const r=await api('/messenger/nudges');if(r.count){nudgeCount=r.count;const names=[...new Set((r.nudges||[]).map(n=>notes[n.sender_id]?.name||friends.find(f=>f.id===n.sender_id)?.name||'A friend'))];const message='✨ '+(names.length===1?names[0]+' nudged you!':names.length+' friends nudged you!');if(page==='chat')showChatFeedback(message);else toast(message);retroSound('nudge');if(page==='home')render();if(page==='messenger')render();setTimeout(()=>{nudgeCount=0;if(page==='home')render()},4000)}}catch(e){console.warn('Nudge check',e)}finally{nudgePollBusy=false}}
let chatAttentionIds=new Set(),chatAttentionUntil=0,chatAttentionTimer=null,chatInitialLoaded=false;
function markChatAttention(messages,peer){
 const key='ping_chat_seen_'+me.id+'_'+peer;
 const seen=get(key,[]);
 const inbound=messages.filter(m=>m.sender_id!==me.id);
 const fresh=seen.length?inbound.filter(m=>!seen.includes(m.id)):inbound.slice(-3);
 if(fresh.length){
  chatAttentionIds=new Set(fresh.map(m=>m.id));chatAttentionUntil=Date.now()+5000;
  clearTimeout(chatAttentionTimer);
  chatAttentionTimer=setTimeout(()=>{chatAttentionIds.clear();chatAttentionUntil=0;document.querySelectorAll('.msn-message.new-arrival').forEach(el=>el.classList.remove('new-arrival'))},5050);
 }
 // Keep the most recent IDs; this prevents old messages from bouncing again on revisit.
 put(key,inbound.slice(-150).map(m=>m.id));
}
function openChat(id){if(!friends.some(f=>f.id===id))return toast('Friend unavailable');chatPeer=id;page='chat';chatMessages=[];chatLastIncoming='';chatInitialLoaded=false;chatAttentionIds.clear();chatAttentionUntil=0;clearTimeout(chatAttentionTimer);render();loadChat();pollChatTyping();if(chatTimer)clearInterval(chatTimer);chatTimer=setInterval(()=>{if(page==='chat'&&document.visibilityState==='visible'){loadChat(true);pollChatTyping()}},3000)}
function chatView(){const f=friends.find(x=>x.id===chatPeer);if(!f)return '<section class="panel">Friend unavailable.</section>';return `<section class="msn-chat-window"><div class="msn-chat-header"><button class="msn-chat-back" onclick="closeChat()" aria-label="Back to friends">‹</button><div class="msn-chat-identity"><strong>💬 ${esc(notes[f.id]?.name||f.name)}</strong><small>${esc(statusText(f))}</small></div><button class="msn-chat-nudge" onclick="sendNudge()" title="Nudge friend">✨ Nudge</button></div><div id="chat-log" class="msn-log" role="log" aria-live="polite">${chatMessages.length?chatMessages.map(chatRow).join(''):'<p class="muted small">No messages yet. Say hello! 👋</p>'}</div><div class="msn-chat-bottom"><div id="chat-typing" class="msn-typing" aria-live="polite"></div><div class="msn-emoji">${['😊','😂','❤️','😭','👍','🥰','👋','🎉'].map(e=>`<button type="button" onclick="insertChatEmoji('${e}')">${e}</button>`).join('')}</div><div class="cam-chat-entry"><button type="button" onclick="openPocketCamFromChat()" aria-label="Take photo with Pocket Cam">📷 Pocket Cam</button></div><form class="msn-compose" onsubmit="sendChat(event)"><input id="chat-input" oninput="onChatTyping()" maxlength="1000" autocomplete="off" placeholder="Type a message…" aria-label="Chat message" enterkeyhint="send"><button type="submit" class="btnaccent">Send ↗</button></form></div></section>`}
function closeChat(){if(chatTimer){clearInterval(chatTimer);chatTimer=null}chatPeer=null;nav('messenger')}
function setChatViewport(){if(!document.body.classList.contains('chat-active'))return;const v=window.visualViewport;document.documentElement.style.setProperty('--chat-height',(v?v.height:window.innerHeight)+'px');document.documentElement.style.setProperty('--chat-top',(v?v.offsetTop:0)+'px')}
if(window.visualViewport){window.visualViewport.addEventListener('resize',setChatViewport);window.visualViewport.addEventListener('scroll',setChatViewport)}window.addEventListener('resize',setChatViewport);

function toggleChatReactions(id){const panel=document.getElementById('reactions-'+id);const toggle=document.getElementById('reaction-toggle-'+id);if(!panel||!toggle)return;const opening=panel.hidden;document.querySelectorAll('.msn-reaction-picker:not([hidden])').forEach(x=>{x.hidden=true;const btn=document.getElementById('reaction-toggle-'+x.id.replace('reactions-',''));if(btn)btn.setAttribute('aria-expanded','false')});panel.hidden=!opening;toggle.setAttribute('aria-expanded',String(opening))}
function chatRow(m){const mine=m.sender_id===me.id;const attention=!mine&&chatAttentionIds.has(m.id)&&Date.now()<chatAttentionUntil;const emoji=['❤️','😂','👍','😮','😢'];if(m.body==='[Pocket Cam photo]')return photoChatRow(m,mine);const active=emoji.filter(e=>Number(m.reactions?.[e]||0)>0);return `<div class="msn-message ${mine?'mine':'theirs'} ${attention?'new-arrival':''}"><div class="msn-message-head">${mine?'You':esc(friends.find(f=>f.id===m.sender_id)?.name||'Friend')} · ${new Date(m.created_at).toLocaleString()}</div><div class="msn-bubble-line"><div class="msn-message-text">${esc(m.body)}</div></div><div class="msn-message-actions"><div class="msn-reactions" aria-label="Message reactions">${active.map(e=>`<button type="button" title="React ${e}" onclick="reactChat('${m.id}','${e}')">${e} ${m.reactions[e]}</button>`).join('')}</div><button type="button" id="reaction-toggle-${m.id}" class="msn-react-trigger" aria-expanded="false" aria-controls="reactions-${m.id}" onclick="toggleChatReactions('${m.id}')" title="React to message" aria-label="React to message">${active.length?'＋':'☺'}</button></div><div class="msn-reaction-picker" id="reactions-${m.id}" hidden>${emoji.map(e=>`<button type="button" title="React ${e}" onclick="reactChat('${m.id}','${e}')">${e}</button>`).join('')}</div></div>`}

function insertChatEmoji(e){const x=$('#chat-input');if(x){x.value+=e;x.focus()}}
async function loadChat(quiet=false){if(!chatPeer)return;const id=chatPeer;try{const r=await api('/messenger/chat/'+encodeURIComponent(id));if(page!=='chat'||chatPeer!==id)return;const incoming=r.messages||[];if(!chatInitialLoaded){chatInitialLoaded=true;markChatAttention(incoming,id)}else{const key='ping_chat_seen_'+me.id+'_'+id;const seen=get(key,[]);const fresh=incoming.filter(m=>m.sender_id!==me.id&&!seen.includes(m.id));if(fresh.length)markChatAttention(incoming,id)}const newest=incoming.filter(m=>m.sender_id!==me.id).at(-1);if(newest&&chatLastIncoming&&newest.id!==chatLastIncoming)retroSound('message');if(newest)chatLastIncoming=newest.id;if(JSON.stringify(chatMessages)!==JSON.stringify(incoming)){const log=$('#chat-log');const nearBottom=!log||log.scrollHeight-log.scrollTop-log.clientHeight<100;const oldTop=log?.scrollTop||0;chatMessages=incoming;if(log){log.innerHTML=chatMessages.length?chatMessages.map(chatRow).join(''):'<p class="muted small">No messages yet. Say hello! 👋</p>';log.scrollTop=nearBottom?log.scrollHeight:oldTop}else render()}}catch(e){if(!quiet)toast(e.message)}}

function messengerWhoosh(){if(!get('ping_retro_sounds',false)||document.visibilityState!=='visible'||effectVolume()===0)return;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const ctx=new C();const duration=.21,rate=ctx.sampleRate,length=Math.ceil(rate*duration),buf=ctx.createBuffer(1,length,rate),out=buf.getChannelData(0);for(let i=0;i<length;i++)out[i]=(Math.random()*2-1);const src=ctx.createBufferSource();src.buffer=buf;const filter=ctx.createBiquadFilter();filter.type='bandpass';filter.frequency.setValueAtTime(1700,ctx.currentTime);filter.frequency.exponentialRampToValueAtTime(500,ctx.currentTime+duration);filter.Q.value=.65;const gain=ctx.createGain();gain.gain.setValueAtTime(.0001,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(Math.max(.0001,.32*effectVolume()),ctx.currentTime+.035);gain.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+duration);src.connect(filter).connect(gain).connect(ctx.destination);src.start();src.stop(ctx.currentTime+duration);src.onended=()=>ctx.close().catch(()=>{})}catch(e){console.warn('Send sound unavailable',e)}}
async function sendChat(event){event.preventDefault();if(chatBusy)return;const input=$('#chat-input'),body=emojiShortcuts(input?.value.trim()||'');if(!body)return;chatBusy=true;try{await api('/messenger/chat/'+encodeURIComponent(chatPeer),'POST',{body});input.value='';messengerWhoosh();await loadChat()}catch(e){toast(e.message)}finally{chatBusy=false}}
async function reactChat(id,emoji){try{await api('/messenger/react/'+encodeURIComponent(id),'POST',{emoji});await loadChat(true)}catch(e){toast(e.message)}}

setInterval(()=>{if(token&&document.visibilityState==='visible')pollMessengerExtras()},12000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&token)pollMessengerExtras()});


// Pocket Cam v37 — photographs stay local until explicitly sent; temporary image data is stored in D1.
const camColors={Silver:'#b8c1cb',Cobalt:'#2555be',Pink:'#e94b9c',Yellow:'#e9c232',Red:'#d73b41',Lime:'#86c83e'};
let camPrefs={style:'classic',layout:'landscape',color:'Silver',stamp:true,...get('ping_cam_prefs',{})};
let camCapturedAt=null,camStream=null,camRaw=null,camProcessed=null,camReturnPeer=null,camZoom=1,camFilter='original',camStrength=75,camNoise=false,camFaded=false,camBusy=false;
function setCamPref(k,v){camPrefs[k]=v;put('ping_cam_prefs',camPrefs);if(page==='camera'){render();startPocketCam()}else render()}
function openPocketCamFromChat(){camReturnPeer=chatPeer;nav('camera')}
function stopPocketCam(){if(camStream){camStream.getTracks().forEach(t=>t.stop());camStream=null}}
function camExit(){stopPocketCam();if(camReturnPeer){const p=camReturnPeer;camReturnPeer=null;openChat(p)}else nav('home')}
function pocketCameraView(){const classic=camPrefs.style==='classic',color=camColors[camPrefs.color]||camColors.Silver;return `<section class="panel pocket-section"><div class="pocket-heading"><h1>📷 Pocket Cam</h1><button class="pill" onclick="camExit()">← Exit</button></div><p class="small muted">Take a little memory. Make it yours. Send it to someone special.</p><div class="pocket-body ${classic?'pocket-classic':'pocket-modern'} ${camPrefs.layout==='portrait'?'pocket-portrait':'pocket-landscape'}" style="--cam-metal:${color}"><div class="pocket-top"><strong>${classic?'PING LAH! DIGITAL':'Pocket Cam'}</strong><span>${classic?'5.0 MEGA · DIGITAL CAMERA':'● Camera'}</span></div><div class="pocket-lcd"><div class="pocket-hud"><span>📷 AUTO · ${camZoom.toFixed(1)}×</span><span>🔴 ▰</span></div><video id="pocket-video" autoplay playsinline muted></video><canvas id="pocket-preview" hidden></canvas><div id="pocket-shutter" class="pocket-shutter"><i></i><i></i></div><div class="pocket-hud pocket-bottom-hud"><span>ISO AUTO</span><span>${new Date().toLocaleDateString()}</span></div></div><div class="pocket-buttons"><button onclick="camAdjustZoom(-.25)" aria-label="Zoom out">− ZOOM</button><button class="pocket-snap" onclick="camSnap()" aria-label="Take photo">📸</button><button onclick="camAdjustZoom(.25)" aria-label="Zoom in">ZOOM +</button></div><div class="pocket-extra"><button onclick="camFlip()">⇄ Flip camera</button><button onclick="camToggleLayout()">⤢ Rotate layout</button></div></div><p id="cam-status" class="small muted" role="status">Allow camera access when prompted.</p><div id="cam-editor" class="cam-editor" ${camRaw?'':'hidden'}><h2>Develop your photo</h2><p class="small muted">Effects are applied to the exported image. Your original stays untouched while editing.</p><div class="cam-photo-wrap"><img id="cam-edited-image" alt="Captured photo preview" ${camProcessed?'src="'+camProcessed+'"':''}></div><label>Photo effect<select id="cam-filter" onchange="camFilter=this.value;camRenderEdit()">${[['original','Original'],['sepia','Sepia 2003'],['mono','Monochrome'],['warm','Vintage Warm'],['cool','Cool Digital'],['fade','Faded Film']].map(([v,l])=>`<option value="${v}" ${camFilter===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Effect strength: <strong id="cam-strength-label">${camStrength}%</strong><input type="range" min="0" max="100" step="5" value="${camStrength}" oninput="camStrength=Number(this.value);document.getElementById('cam-strength-label').textContent=this.value+'%';camRenderEdit()"></label><label class="setting-check"><input type="checkbox" ${camNoise?'checked':''} onchange="camNoise=this.checked;camRenderEdit()"> Subtle digital noise</label><label class="setting-check"><input type="checkbox" ${camFaded?'checked':''} onchange="camFaded=this.checked;camRenderEdit()"> Faded-camera finish</label><label class="setting-check"><input type="checkbox" ${camPrefs.stamp?'checked':''} onchange="setCamPref('stamp',this.checked)"> Date/time stamp and Ping Lah! SG credit</label><div class="cam-actions"><button class="btnmint" onclick="camSave()">↓ Save photo</button><button class="btnaccent" onclick="camShare()">↗ Share outside app</button><button class="btnmint" onclick="camChooseFriend()">💬 Send to friend</button><button class="pill" onclick="camRetake()">↻ Retake</button></div><p class="small muted">Photos sent in Messenger expire 12 hours after the recipient first opens them, or 7 days after sending if earlier. Save photos you want to keep.</p></div><div id="cam-friend-picker" class="cam-friend-picker" hidden><h3>Send to a friend</h3>${friends.map(f=>`<button class="pill" onclick="camSend('${f.id}')">${esc(notes[f.id]?.name||f.name)}</button>`).join('')||'<p>Add a friend first.</p>'}</div></section>`}
async function startPocketCam(){if(page!=='camera')return;const video=document.getElementById('pocket-video');if(!video)return;if(camRaw){video.hidden=true;camRenderEdit();return}stopPocketCam();try{camStream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:camFacing||'environment',width:{ideal:1600},height:{ideal:1200}}});if(page!=='camera'){stopPocketCam();return}video.srcObject=camStream;await video.play();camAdjustZoom(0);document.getElementById('cam-status').textContent='Camera ready · Tap shutter to capture'}catch(e){document.getElementById('cam-status').textContent='Camera unavailable: '+e.message+' · Check Safari camera permission.'}}
let camFacing='environment';function camFlip(){camFacing=camFacing==='environment'?'user':'environment';stopPocketCam();startPocketCam()}
function camToggleLayout(){camPrefs.layout=camPrefs.layout==='landscape'?'portrait':'landscape';put('ping_cam_prefs',camPrefs);render();startPocketCam()}
function camAdjustZoom(delta){camZoom=Math.min(3,Math.max(1,camZoom+delta));const v=document.getElementById('pocket-video');if(v)v.style.transform=`scale(${camZoom})`;const hud=document.querySelector('.pocket-hud span');if(hud)hud.textContent=`📷 AUTO · ${camZoom.toFixed(1)}×`}
function camSnapSound(){if(!get('ping_retro_sounds',false)||effectVolume()===0)return;try{const C=window.AudioContext||window.webkitAudioContext,ctx=new C(),length=Math.floor(ctx.sampleRate*.09),b=ctx.createBuffer(1,length,ctx.sampleRate),d=b.getChannelData(0);for(let i=0;i<length;i++)d[i]=(Math.random()*2-1)*Math.exp(-i/length*12);const src=ctx.createBufferSource(),g=ctx.createGain();src.buffer=b;g.gain.value=Math.min(.4,effectVolume()*.32);src.connect(g).connect(ctx.destination);src.start();src.onended=()=>ctx.close().catch(()=>{})}catch(e){console.warn('Shutter audio',e)}}
function camSnap(){const v=document.getElementById('pocket-video');if(!v||!v.videoWidth||camBusy)return;camBusy=true;const shutter=document.getElementById('pocket-shutter');shutter?.classList.add('snap');camSnapSound();const c=document.createElement('canvas'),ratio=camPrefs.layout==='portrait'?3/4:4/3;let w=camPrefs.layout==='portrait'?1200:1600,h=camPrefs.layout==='portrait'?1600:1200;c.width=w;c.height=h;const ctx=c.getContext('2d'),vw=v.videoWidth,vh=v.videoHeight,cropW=Math.min(vw,vh*ratio)/camZoom,cropH=cropW/ratio;ctx.drawImage(v,(vw-cropW)/2,(vh-cropH)/2,cropW,cropH,0,0,w,h);camCapturedAt=new Date();camRaw=c.toDataURL('image/jpeg',.94);setTimeout(()=>{camBusy=false;stopPocketCam();render();camRenderEdit()},310)}
function camRenderEdit(){if(!camRaw)return;const img=new Image();img.onload=()=>{const c=document.createElement('canvas');c.width=img.width;c.height=img.height;const x=c.getContext('2d'),s=camStrength/100;let f='none';if(camFilter==='sepia')f=`sepia(${s}) contrast(${1+s*.1})`;if(camFilter==='mono')f=`grayscale(${s}) contrast(${1+s*.12})`;if(camFilter==='warm')f=`sepia(${s*.5}) saturate(${1+s*.4})`;if(camFilter==='cool')f=`hue-rotate(${s*155}deg) saturate(${1-s*.22})`;if(camFilter==='fade')f=`sepia(${s*.3}) contrast(${1-s*.25}) brightness(${1+s*.1})`;x.filter=f;x.drawImage(img,0,0);x.filter='none';if(camFaded){x.fillStyle='rgba(250,218,171,.085)';x.fillRect(0,0,c.width,c.height)}if(camNoise){const pixels=x.getImageData(0,0,c.width,c.height);for(let i=0;i<pixels.data.length;i+=4){const n=(Math.random()-.5)*18;for(let j=0;j<3;j++)pixels.data[i+j]=Math.max(0,Math.min(255,pixels.data[i+j]+n))}x.putImageData(pixels,0,0)}if(camPrefs.stamp){const size=Math.round(c.width*.027),pad=Math.round(c.width*.022);x.font=`bold ${size}px monospace`;x.textBaseline='bottom';const date=(camCapturedAt||new Date()).toLocaleString('en-GB',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:false});x.lineWidth=3;x.strokeStyle='rgba(0,0,0,.85)';x.fillStyle='#ff9b43';x.textAlign='right';x.strokeText(date,c.width-pad,c.height-pad);x.fillText(date,c.width-pad,c.height-pad);x.textAlign='left';x.font=`bold ${Math.round(size*.62)}px sans-serif`;x.strokeText('PING LAH! SG',pad,c.height-pad);x.fillStyle='#f7f4ee';x.fillText('PING LAH! SG',pad,c.height-pad)}camProcessed=c.toDataURL('image/jpeg',.86);const e=document.getElementById('cam-edited-image');if(e)e.src=camProcessed};img.src=camRaw}
function camRetake(){camRaw=null;camProcessed=null;camCapturedAt=null;render();startPocketCam()}
function pocketPhotoFile(data,name){const parts=data.split(','),raw=atob(parts[1]),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);return new File([bytes],name,{type:'image/jpeg'});}
function pocketPhotoDownload(data,name){const a=document.createElement('a');a.href=data;a.download=name;document.body.append(a);a.click();a.remove();}
function pocketPhotoSaveFallback(data,name){const w=window.open('','_blank');if(w){w.document.write('<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Save Pocket Cam Photo</title></head><body style="margin:0;background:#121820;color:white;font:16px system-ui;text-align:center;padding:18px"><p>Press and hold the photo, then choose <b>Save to Photos</b> or <b>Save Image</b>.</p><img style="max-width:100%;height:auto" alt="Your Pocket Cam photo" src="'+data+'"></body></html>');w.document.close()}else{pocketPhotoDownload(data,name);toast('If not in Photos, check Files → Downloads or use Share → Save Image.')}}
async function pocketPhotoSave(data,name){if(!data)return toast('Take a photo first');let file;try{file=pocketPhotoFile(data,name)}catch(e){return toast('Unable to prepare photo')}
  if(navigator.share && (!navigator.canShare || navigator.canShare({files:[file]}))){try{await navigator.share({files:[file],title:'Pocket Cam · Ping Lah! SG'});return}catch(e){if(e.name==='AbortError')return}}
  pocketPhotoSaveFallback(data,name);
}
function camSave(){return pocketPhotoSave(camProcessed,'ping-lah-pocket-cam-'+Date.now()+'.jpg')}
function camShare(){return pocketPhotoSave(camProcessed,'ping-lah-pocket-cam-'+Date.now()+'.jpg')}
function camChooseFriend(){if(!camProcessed)return toast('Take a photo first');document.getElementById('cam-friend-picker').hidden=false;document.getElementById('cam-friend-picker').scrollIntoView({behavior:'smooth',block:'nearest'})}
async function camSend(peer){if(camBusy||!camProcessed)return;camBusy=true;try{const img=new Image();await new Promise((res,rej)=>{img.onload=res;img.onerror=rej;img.src=camProcessed});const c=document.createElement('canvas'),scale=Math.min(640/img.width,480/img.height,1);c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);let data='';for(const q of [.72,.58,.44,.32]){data=c.toDataURL('image/jpeg',q);if(data.length<145000)break}if(data.length>145000)throw Error('Photo too large; please retake');await api('/messenger/photo/'+encodeURIComponent(peer),'POST',{image:data});toast('Photo sent!');camReturnPeer=null;camRaw=null;camProcessed=null;openChat(peer)}catch(e){toast('Could not send photo: '+e.message)}finally{camBusy=false}}
function photoChatRow(m,mine){const expires=m.photo_expires_at,opened=m.photo_opened_at,dead=m.photo_expired;const when=expires?new Date(Number(expires)).toLocaleString():'';return `<div class="msn-message ${mine?'mine':'theirs'}"><div class="msn-message-head">${mine?'You':esc(friends.find(f=>f.id===m.sender_id)?.name||'Friend')} · ${new Date(m.created_at).toLocaleString()}</div><div class="msn-bubble-line"><div class="msn-message-text photo-message">${dead?'⌛ Photo expired':`<strong>📷 Pocket Cam photo</strong><p class="small">${opened?'Available until '+esc(when):'12 hours after first opening · maximum 7 days'}</p><button class="pill" onclick="openChatPhoto('${m.id}')">${opened?'View photo again':'View photo'}</button>`}</div></div></div>`}
async function openChatPhoto(id){try{const r=await api('/messenger/photo/'+encodeURIComponent(id),'POST');if(!r.image)return toast('Photo unavailable');const overlay=document.createElement('div');overlay.className='photo-lightbox';overlay.innerHTML=`<div class="photo-lightbox-inner"><button class="pill" onclick="this.closest('.photo-lightbox').remove()">✕ Close</button><img alt="Photo from Messenger" src="${r.image}"><p>Available until ${new Date(Number(r.expires_at)).toLocaleString()}</p><button class="pill" onclick="saveChatPhoto('${id}')">↓ Save photo</button></div>`;document.body.append(overlay);await loadChat(true)}catch(e){toast(e.message);await loadChat(true)}}
async function saveChatPhoto(id){try{const r=await api('/messenger/photo/'+encodeURIComponent(id),'GET');if(!r.image)throw Error('Photo unavailable');await pocketPhotoSave(r.image,'ping-lah-friend-photo-'+Date.now()+'.jpg')}catch(e){toast('Could not save photo: '+e.message)}}
// On entry, acquire camera after the UI has been rendered.
const originalNavPocket=nav;nav=function(p,id){originalNavPocket(p,id);if(p==='camera')startPocketCam()};
